import type { CSSProperties, ReactNode } from "react";

/**
 * Official brand artwork (generated by `npm run brand:build`, served from apps/*\/public/brand).
 * Intrinsic sizes are read from the PNG headers; width/height are always set so the layout never shifts.
 */
export const BRAND_ASSETS = {
  logo: { src: "logo-light.png", w: 800, h: 665 }, // stacked: mark + UNIMATE.AZ + tagline, light backgrounds
  mark: { src: "mark.png", w: 320, h: 380 }, // brandmark, light backgrounds
  tile: { src: "mark-tile.png", w: 320, h: 320 }, // brandmark on its gradient tile, dark backgrounds
  wordmark: { src: "wordmark-white.png", w: 640, h: 113 }, // white wordmark, dark backgrounds
} as const;

export type BrandVariant = "auto" | "light" | "dark";
type Asset = (typeof BRAND_ASSETS)[keyof typeof BRAND_ASSETS];

interface BrandBase {
  /** Translated accessible name (t("brand.logo") / t("brand.mark")). */
  label: string;
  /** light = artwork for light backgrounds, dark = for dark backgrounds, auto = follows the theme (CSS only, no JS). */
  variant?: BrandVariant;
  /** Public path where /brand/* is served. */
  basePath?: string;
  className?: string;
}

function Img({ asset, h, base }: { asset: Asset; h: number; base: string }) {
  const height = Math.round(h);
  const width = Math.round((h * asset.w) / asset.h);
  return <img src={`${base}/${asset.src}`} width={width} height={height} alt="" decoding="async" draggable={false} />;
}

function Wrap({ label, variant, className, row, children }: { label: string; variant: BrandVariant; className: string | undefined; row?: boolean; children: ReactNode }) {
  const cls = ["um-brand", `um-brand--${variant}`, row && "um-brand--row", className].filter(Boolean).join(" ");
  return (
    <span className={cls} role="img" aria-label={label}>
      {children}
    </span>
  );
}

/**
 * BrandMark: the graduation-cap "U" only. Light = mark.png, dark = mark-tile.png (gradient tile).
 * `height` is the rendered height in px.
 */
export function BrandMark({ label, variant = "auto", height = 32, basePath = "/brand", className }: BrandBase & { height?: number }) {
  return (
    <Wrap label={label} variant={variant} className={className}>
      {variant !== "dark" ? (
        <span className="um-brand__pair um-brand__light">
          <Img asset={BRAND_ASSETS.mark} h={height} base={basePath} />
        </span>
      ) : null}
      {variant !== "light" ? (
        <span className="um-brand__pair um-brand__dark">
          <Img asset={BRAND_ASSETS.tile} h={height} base={basePath} />
        </span>
      ) : null}
    </Wrap>
  );
}

/**
 * BrandLogo: mark + UNIMATE.AZ wordmark.
 * - layout "stacked" (default): light = logo-light.png; dark = mark-tile.png above wordmark-white.png.
 * - layout "row": dark artwork only (tile + wordmark side by side, e.g. the always-dark sidebar). There is no official
 *   horizontal light lockup, so the light part of a row logo falls back to the stacked logo.
 * `height` is the total rendered height in px.
 */
export function BrandLogo({ label, variant = "auto", layout = "stacked", height = 96, basePath = "/brand", className }: BrandBase & { layout?: "stacked" | "row"; height?: number }) {
  const row = layout === "row";
  const lightW = (height * BRAND_ASSETS.logo.w) / BRAND_ASSETS.logo.h;
  // Stacked dark lockup is as tall as the light logo; the row lockup is `height` tall.
  const tileH = row ? height : lightW * 0.5;
  const wordW = row ? height * 3.1 : lightW * 0.9;
  const wordH = (wordW * BRAND_ASSETS.wordmark.h) / BRAND_ASSETS.wordmark.w;
  const gap: CSSProperties = { gap: Math.round(height * (row ? 0.22 : 0.05)) };
  return (
    <Wrap label={label} variant={variant} className={className} row={row}>
      {variant !== "dark" ? (
        <span className="um-brand__pair um-brand__light">
          <Img asset={BRAND_ASSETS.logo} h={height} base={basePath} />
        </span>
      ) : null}
      {variant !== "light" ? (
        <span className="um-brand__pair um-brand__dark" style={gap}>
          <Img asset={BRAND_ASSETS.tile} h={tileH} base={basePath} />
          <Img asset={BRAND_ASSETS.wordmark} h={wordH} base={basePath} />
        </span>
      ) : null}
    </Wrap>
  );
}
